use std::path::{Path, PathBuf};

pub fn gather(a: &str) -> Result<Vec<PathBuf>, i32> {
    let base = std::fs::canonicalize("/app/vatlogs").map_err(|_| 2)?;
    let root = std::fs::canonicalize(a).map_err(|_| 2)?;
    if !root.starts_with(&base) || !root.is_dir() {
        return Err(2);
    }
    let mut files = Vec::new();
    descend(&root, &base, &mut files)?;
    files.sort();
    if files.is_empty() {
        return Err(3);
    }
    Ok(files)
}

fn descend(dir: &Path, base: &Path, out: &mut Vec<PathBuf>) -> Result<(), i32> {
    let rd = std::fs::read_dir(dir).map_err(|_| 2)?;
    for item in rd {
        let item = item.map_err(|_| 2)?;
        let ty = item.file_type().map_err(|_| 2)?;
        if ty.is_symlink() {
            return Err(2);
        }
        let path = item.path();
        let canon = std::fs::canonicalize(&path).map_err(|_| 2)?;
        if !canon.starts_with(base) {
            return Err(2);
        }
        if ty.is_dir() {
            descend(&canon, base, out)?;
        } else if ty.is_file() {
            out.push(canon);
        } else {
            return Err(2);
        }
    }
    Ok(())
}
