pub fn take(text: &str) -> Result<(String, Vec<String>), i32> {
    if text.trim().is_empty() {
        return Err(3);
    }
    let mut kind: Option<String> = None;
    let mut frames = Vec::new();
    let mut expected = 0usize;
    let mut summary = false;

    for line in text.lines() {
        if line.contains("ERROR:") {
            if kind.is_some() {
                return Err(3);
            }
            let rest = line.split_once("ERROR:").ok_or(3)?.1.trim();
            let after = rest.strip_prefix("AddressSanitizer:").ok_or(3)?.trim();
            let value = after.split(" on ").next().unwrap_or("").trim();
            if value.is_empty() {
                return Err(3);
            }
            kind = Some(value.to_string());
            continue;
        }
        let trimmed = line.trim_start();
        if trimmed.starts_with('#') {
            if kind.is_none() || summary {
                return Err(3);
            }
            let mut words = trimmed.split_whitespace();
            let number = words.next().ok_or(3)?;
            let n = number.strip_prefix('#').ok_or(3)?.parse::<usize>().map_err(|_| 3)?;
            if n != expected {
                return Err(3);
            }
            expected += 1;
            let marker = words.position(|w| w == "in").ok_or(3)?;
            let all: Vec<&str> = trimmed.split_whitespace().collect();
            let sym_index = marker + 2;
            let sym = all.get(sym_index).ok_or(3)?;
            if sym.is_empty() {
                return Err(3);
            }
            frames.push(normalize(sym));
            continue;
        }
        if trimmed.starts_with("SUMMARY:") {
            if kind.is_none() || expected == 0 {
                return Err(3);
            }
            summary = true;
        }
    }

    if !summary || kind.is_none() || frames.is_empty() {
        return Err(3);
    }
    let user: Vec<String> = frames.into_iter().filter(|s| {
        !s.contains("__asan") && !s.contains("__interceptor") && !s.contains("__hwasan")
    }).collect();
    if user.is_empty() {
        return Err(3);
    }
    Ok((kind.unwrap(), user))
}

fn normalize(s: &str) -> String {
    let b = s.as_bytes();
    let mut out = String::new();
    let mut i = 0;
    while i < b.len() {
        if i + 2 <= b.len() && b[i] == b'0' && (b[i + 1] == b'x' || b[i + 1] == b'X') {
            let mut j = i + 2;
            while j < b.len() && b[j].is_ascii_hexdigit() {
                j += 1;
            }
            if j > i + 2 {
                out.push_str("<hex>");
                i = j;
                continue;
            }
        }
        let ch = s[i..].chars().next().unwrap();
        out.push(ch);
        i += ch.len_utf8();
    }
    out
}
