#[path = "../treyfun/clip.rs"]
mod clip;

use std::collections::BTreeMap;

#[derive(Clone)]
pub struct Rec {
    pub issue: i32,
    pub kind: String,
    pub frames: Vec<String>,
    pub body: String,
}

pub fn tally(root: &str) -> Result<Vec<Rec>, i32> {
    let paths = crate::walk::gather(root)?;
    let mut bag: BTreeMap<Vec<String>, Rec> = BTreeMap::new();
    for path in paths {
        let text = std::fs::read_to_string(path).map_err(|_| 3)?;
        let (kind, frames) = clip::take(&text)?;
        let body = frames.join(" | ");
        let rec = Rec { issue: 0, kind, frames: frames.clone(), body };
        if let Some(old) = bag.get(&frames) {
            if old.kind != rec.kind || old.body != rec.body {
                return Err(3);
            }
        } else {
            bag.insert(frames, rec);
        }
    }
    if bag.is_empty() {
        return Err(3);
    }
    let mut recs: Vec<Rec> = bag.into_values().collect();
    for (i, rec) in recs.iter_mut().enumerate() {
        rec.issue = i as i32 + 1;
    }
    Ok(recs)
}
